SELECT p.id, p.first_name, p.last_name FROM persons p INNER JOIN person_crimes pc on p.id = pc.person_id INNER JOIN locations l on p.location_id = l.id
WHERE l.id = 11 and role = 'suspect'
ORDER by p.id;

SELECT p.id, p.first_name, p.last_name FROM persons p INNER JOIN person_crimes pc on p.id = pc.person_id INNER JOIN crimes c on pc.crime_id = c.id
WHERE occupation = 'Accountant' AND crime_type = 'Cybercrime'
ORDER by p.id;

SELECT p.id, p.first_name, p.last_name FROM persons p 
WHERE occupation = 'Software Developer' AND age < 30
ORDER by p.id;

SELECT p.id, p.first_name, p.last_name FROM persons p INNER JOIN person_crimes pc on p.id = pc.person_id INNER JOIN locations l on p.location_id = l.id
WHERE occupation = 'Sales Manager' AND role = 'witness' AND l.id = 7
ORDER by p.id;

SELECT p.id, p.first_name, p.last_name FROM persons p INNER JOIN person_crimes pc on p.id = pc.person_id INNER JOIN crimes c on pc.crime_id = c.id
