SELECT p.id, p.first_name, p.last_name, pc.crime_id FROM persons p INNER JOIN person_crimes pc on p.id = pc.person_id INNER JOIN crimes c on pc.crime_id = c.id
WHERE occupation = 'Nurse' AND crime_type = 'Assault'
